appearance.custom_css:
/* Motion / Protection 1.0 — sport-minded protection, mobile-first */
.cms-page{--site-width:1280px;--page-radius:1rem;background:#f0f7f8;color:#173044;font-family:Manrope,"Segoe UI",Arial,sans-serif;line-height:1.75}
.cms-page .site-container{width:min(calc(100% - 4rem),1280px)}
.cms-page .site-header{position:relative;z-index:6;background:#091d31;color:#ecf7ff;border:0}
.cms-page .header-inner{min-height:94px;gap:2rem}
.cms-page .site-brand{font-size:clamp(1.1rem,1.9vw,1.5rem);font-weight:850;letter-spacing:-.035em;max-width:410px}
.cms-page .site-brand::before{content:"✚";display:inline-grid;place-items:center;width:2.1rem;height:2.1rem;background:#9cf2d8;border-radius:.72rem;margin-right:.65rem;color:#0e3141;font-size:1.05rem;transform:rotate(-8deg)}
.cms-page .site-navigation>ul{gap:.25rem}
.cms-page .site-navigation a{font-size:.81rem;letter-spacing:.005em;font-weight:750;text-decoration:none!important;padding:.72rem .9rem;border-radius:99px;transition:background .2s}
.cms-page .site-navigation a:hover,.cms-page .site-navigation a[aria-current]{background:#19445a;color:#e8fff7}
.cms-page .site-navigation ul ul{background:#0d2d43;border:1px solid #386071}
.cms-page .landing-intro{width:100%;max-width:none;min-height:clamp(550px,68vh,770px);padding:6rem max(2rem,calc((100vw - 1280px)/2));display:flex;align-items:center;position:relative;isolation:isolate;overflow:hidden;text-align:left;background:#061626}
.cms-page .landing-intro::before{content:"";position:absolute;inset:0;z-index:-3;background:linear-gradient(92deg,#061b2c 3%,#082b3bdf 36%,#07273990 61%,#0c263843 100%),url("https://images.unsplash.com/photo-1779104782112-3c890f523ec5?auto=format&fit=crop&w=1800&q=85") center 44%/cover no-repeat}
.cms-page .landing-intro::after{content:"";position:absolute;inset:auto -9% -55% auto;width:min(66vw,860px);aspect-ratio:1;border:clamp(30px,6vw,90px) solid #9cf2d82a;border-radius:50%;z-index:-2;box-shadow:0 0 0 48px #9cf2d80c;pointer-events:none}
.cms-page .landing-intro .page-intro{margin:0;max-width:920px;padding:0}
.cms-page .page-eyebrow{display:inline-block;background:#b7fee9;color:#072a3b;border-radius:99px;padding:.5rem 1.1rem;font-weight:800;font-size:.78rem;letter-spacing:.07em;box-shadow:0 8px 22px #0002;text-transform:uppercase;margin:0 0 2rem}
.cms-page h1{font-size:clamp(3.5rem,7.25vw,7.4rem);max-width:13ch;color:#fff;line-height:1.015;letter-spacing:-.068em;font-weight:850;text-wrap:balance}
.cms-page .landing-intro .page-intro::after{content:"WISSEN. VORBEUGEN. ABGESICHERT SEIN.";display:block;max-width:600px;color:#c4f9e9;border-left:4px solid #b4ffe7;font-size:clamp(.82rem,1.4vw,1rem);line-height:1.55;letter-spacing:.11em;font-weight:800;padding:.4rem 1.2rem;margin-top:2.3rem}
.cms-page .landing-body>.page-content{background:#f0f7f8;border:0;padding:clamp(3.3rem,6vw,6rem) min(3vw,3rem) 7rem;min-height:30rem}
.cms-page .page-content>.rich{max-width:100%;font-size:1.05rem;line-height:1.85;color:#3b5664}
.cms-page .page-content>.rich>p:first-child{font-size:clamp(1.25rem,2vw,1.68rem);max-width:78ch;line-height:1.7;font-weight:560;color:#14384b}
.cms-page .page-content h2{color:#0c3249;font-weight:850;font-size:clamp(1.9rem,3vw,3.2rem);line-height:1.16;letter-spacing:-.05em;max-width:28ch;margin-top:3.5rem;margin-bottom:1.5rem}
.cms-page .page-content h2::before{content:"";display:block;width:68px;height:6px;background:#14af92;border-radius:99px;margin-bottom:1.15rem}
.cms-page .page-content h3{color:#0c3449;font-weight:800;font-size:1.28rem}
.cms-page .page-content ul{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1.1rem;margin-block:2.5rem}
.cms-page .page-content li{position:relative;padding:1.5rem 1.3rem 1.5rem 3.2rem;background:#fff;box-shadow:0 15px 35px #0942540a;border:1px solid #d8e6e7;border-radius:1.15rem;color:#153c4c;font-weight:690}
.cms-page .page-content li::before{content:"✓";position:absolute;left:1.25rem;top:1.38rem;display:grid;place-items:center;width:1.27rem;height:1.27rem;background:#b5fce7;color:#075d4f;font-size:.84rem;font-weight:900;border-radius:100%}
.cms-page .page-content a{font-weight:800;color:#006f71;text-decoration-color:#30af9f;text-underline-offset:.2em}
.cms-page .page-content a:hover{color:#063b59}
.cms-page .page-content blockquote{border-left:5px solid #13b89e;background:#e1f4ed;border-radius:0 1rem 1rem 0;padding:1.5rem 2rem;color:#163b45}
.cms-page .page-content table{background:#fff;border:1px solid #d7e8e8;border-collapse:separate;border-spacing:0;border-radius:1rem;overflow:hidden;box-shadow:0 14px 35px #08334c0b}
.cms-page .page-content th{background:#10394f;color:#fff;font-weight:750}
.cms-page .page-content td{border-bottom:1px solid #e3efef}
.cms-page .site-footer{background:#081d2f;color:#e6f7f5;padding-block:4rem 2rem;border:0}
.cms-page .footer-inner{gap:5rem}
.cms-page .site-footer .site-brand{font-size:1.5rem;color:#fff}
.cms-page .site-footer p,.cms-page .site-footer a{color:#c0d4df}
.cms-page .site-footer a:hover{color:#b7fee9}
.cms-page .cms-block{background:#fff;border:1px solid #d8edeb;box-shadow:0 12px 30px #0957620d;border-radius:1.25rem}
.cms-page .cms-block-cta>a.join{background:#0d3950;color:#effffb;border-radius:99px}
@media(min-width:901px){.cms-page .page-content>.rich>p{max-width:83ch}}
@media(max-width:900px){.cms-page .site-container{width:calc(100% - 2rem)}.cms-page .landing-intro{padding-inline:2rem}.cms-page h1{font-size:clamp(3.2rem,10vw,6.3rem)}}
@media(max-width:760px){.cms-page .header-inner{gap:1.15rem;padding-block:1.2rem}.cms-page .site-brand{font-size:1.16rem}.cms-page .site-navigation{width:100%;overflow:visible}.cms-page .site-navigation>ul{gap:.1rem}.cms-page .site-navigation a{font-size:.72rem;padding:.53rem .65rem}.cms-page .landing-intro{min-height:530px;padding:4rem 1.3rem}.cms-page .landing-intro::before{background:linear-gradient(90deg,#071c2ef2,#072e40a8),url("https://images.unsplash.com/photo-1779104782112-3c890f523ec5?auto=format&fit=crop&w=1000&q=80") 60% center/cover}.cms-page .landing-intro .page-intro::after{max-width:320px;font-size:.76rem}.cms-page .landing-body>.page-content{padding:3rem 1rem 5rem}.cms-page .page-content li{padding:1.15rem 1.1rem 1.15rem 2.85rem}.cms-page .page-content li::before{left:.95rem;top:1.12rem}.cms-page .site-footer{padding-block:3rem}}
@media(prefers-reduced-motion:reduce){.cms-page *{transition:none!important}}
